// The checklist observes the existing mission state; completion requires the actual exercise.
const locations={transformer:'Transformador',rectifier:'Rectificador',control:'Tablero auxiliar',battery:'Banco de baterías'};
export class MaintenanceChecklist179{
 constructor(ui,missions){this.ui=ui;this.missions=missions;const d=ui.doc;this.root=d.createElement('section');this.root.className='maint179-checklist';this.root.setAttribute('aria-label','Lista de mantenimiento');this.root.innerHTML='<header><small>PLAN DE INTERVENCIÓN</small><h3>¿Dónde trabajamos?</h3><output data-check179-total></output></header><nav data-check179-missions aria-label="Equipos para mantenimiento"></nav><section class="maint179-current"><small data-check179-location></small><h4 data-check179-title></h4><p data-check179-next></p><button type="button" data-check179-locate>Ubicar trabajo actual · F</button><ol data-check179-steps aria-label="Pasos de la intervención"></ol></section>';
  ui.panel.prepend(this.root);const panel184=ui.panel.parentElement;panel184.id='maint184-plan';this.close184=d.createElement('button');this.close184.type='button';this.close184.className='maint184-close';this.close184.textContent='Ocultar menú ×';this.close184.onclick=()=>this.setJournal182(false);this.root.prepend(this.close184);this.root.append(ui.nav177.root);const list=this.root.querySelector('[data-check179-missions]');for(const[id,m]of Object.entries(missions)){const b=d.createElement('button');b.type='button';b.dataset.check179Mission=id;b.innerHTML='<span data-check179-icon aria-hidden="true">○</span><span><small>'+ (locations[m.part]||m.part)+'</small><strong>'+m.title+'</strong></span>';b.onclick=()=>{if(ui.busy||id===ui.state.id)return;this.setJournal182(false);void ui.start(id);};list.append(b);}this.root.querySelector('[data-check179-locate]').onclick=()=>ui.play135.focus();
  this.pad=d.createElement('nav');this.pad.className='maint179-pad';this.pad.setAttribute('aria-label','Desplazamiento con mouse');this.pad.innerHTML='<small>MOVERSE</small>';for(const[key,label,symbol]of [['w','Caminar hacia adelante','↑'],['a','Caminar a la izquierda','←'],['s','Caminar hacia atrás','↓'],['d','Caminar a la derecha','→'],['turnleft','Girar a la izquierda','↶'],['turnright','Girar a la derecha','↷'],['lookup','Mirar arriba','⌃'],['lookdown','Mirar abajo','⌄']]){const b=d.createElement('button');b.type='button';b.dataset.walk179=key;b.textContent=symbol;b.setAttribute('aria-label',label);const end=()=>ui.view.walk176?.input179(key,false);b.addEventListener('pointerdown',e=>{if(e.button!==0||ui.busy)return;e.preventDefault();b.setPointerCapture?.(e.pointerId);ui.view.walk176?.input179(key,true);});for(const type of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(type,end);b.addEventListener('keydown',e=>{if([' ','Enter'].includes(e.key)){e.preventDefault();ui.view.walk176?.input179(key,true);}});b.addEventListener('keyup',end);b.addEventListener('blur',end);this.pad.append(b);}ui.view.canvas.parentElement.append(this.pad);
  this.toggle182=d.createElement('button');this.toggle182.type='button';this.toggle182.className='maint182-journal-toggle';this.toggle182.textContent='☰ Menú · J';this.toggle182.setAttribute('aria-expanded','false');this.toggle182.setAttribute('aria-controls','maint184-plan');this.toggle182.onclick=()=>this.setJournal182(ui.dialog.dataset.journal182!=='true');ui.view.canvas.parentElement.append(this.toggle182);
  this.objective182=d.createElement('section');this.objective182.className='maint182-objective';this.objective182.setAttribute('aria-label','Objetivo actual');this.objective182.innerHTML='<small data-fps182-count></small><strong data-fps182-title></strong><p data-fps182-step></p><output data-fps182-feedback role="status" aria-live="polite"></output>';ui.view.canvas.parentElement.append(this.objective182);this.render();
 }
 setJournal182(open){this.ui.dialog.dataset.journal182=String(open);this.ui.panel.parentElement.inert=this.ui.active&&!open;this.toggle182.setAttribute('aria-expanded',String(open));this.toggle182.textContent=open?'× Cerrar menú · J':'☰ Menú · J';if(open){this.ui.view.walk176?.releaseMouse182();this.ui.view.walk176?.keys.clear();}if(!open&&this.ui.active)this.ui.view.canvas.focus?.({preventScroll:true});this.ui.view.resize?.();}
 render(){const ui=this.ui,s=ui.state;this.root.hidden=!ui.active;ui.panel.parentElement.inert=ui.active&&ui.dialog.dataset.journal182!=='true';this.toggle182.hidden=!ui.active;this.objective182.hidden=!ui.active;this.objective182.querySelector('[data-fps182-count]').textContent=s.done?'INTERVENCIÓN COMPROBADA':'OBJETIVO · '+(s.index+1)+' / '+s.mission.steps.length;this.objective182.querySelector('[data-fps182-title]').textContent=s.mission.title;this.objective182.querySelector('[data-fps182-step]').textContent=ui.busy?'Preparando equipo…':s.done?'Pulsa J para elegir otro trabajo.':s.step.text;this.objective182.querySelector('[data-fps182-feedback]').textContent=!ui.busy&&s.feedback.startsWith('Preparando')?'':s.feedback;this.pad.hidden=!ui.active||ui.busy;this.root.querySelector('[data-check179-total]').textContent=Object.values(ui.completed).filter(Boolean).length+' / '+Object.keys(this.missions).length+' intervenciones comprobadas';for(const b of this.root.querySelectorAll('[data-check179-mission]')){const id=b.dataset.check179Mission;b.disabled=ui.busy;b.setAttribute('aria-current',id===s.id?'true':'false');b.dataset.state=ui.completed[id]?'done':id===s.id?'current':'pending';b.querySelector('[data-check179-icon]').textContent=ui.completed[id]?'✓':id===s.id?'●':'○';}this.root.querySelector('[data-check179-location]').textContent=locations[s.mission.part]||s.mission.part;this.root.querySelector('[data-check179-title]').textContent=s.mission.title;this.root.querySelector('[data-check179-next]').textContent=ui.busy?'Preparando el equipo…':s.done?'Intervención comprobada. Elige otro equipo.':'Paso '+(s.index+1)+' de '+s.mission.steps.length;this.root.querySelector('[data-check179-locate]').disabled=ui.busy||!ui.bench||s.done;const signature=s.id+':'+s.index;if(signature!==this.last){this.last=signature;const list=this.root.querySelector('[data-check179-steps]');list.innerHTML='';list.append(...s.mission.steps.map((step,i)=>{const li=ui.doc.createElement('li');li.dataset.state=i<s.index?'done':i===s.index?'current':'pending';if(i===s.index)li.setAttribute('aria-current','step');li.innerHTML='<span aria-hidden="true">'+(i<s.index?'✓':String(i+1).padStart(2,'0'))+'</span><p>'+step.text+'</p>';return li;}));}}
}
